function validate([mat, k]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 25) return 'mat needs 1 to 25 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 25) return 'Each row needs 1 to 25 values.';
  if (mat.some(r => r.length !== n)) return 'All rows must have the same length.';
  if (mat.some(r => r.some(v => !Number.isInteger(v) || v < 1 || v > 25))) return 'Each value is an integer from 1 to 25.';
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is an integer from 1 to 50.';
  return null;
}

