function areSimilar(mat, k) {
  const cols = mat[0].length;
  const shift = k % cols;

  for (let row = 0; row < mat.length; row++) {
    const original = mat[row];
    const moved = new Array(cols);
    for (let col = 0; col < cols; col++) {
      if (row % 2 === 0) {
        moved[col] = original[(col + shift) % cols];
      } else {
        moved[col] = original[(col - shift + cols) % cols];
      }
    }
    for (let col = 0; col < cols; col++) {
      if (moved[col] !== original[col]) {
        return false;
      }
    }
  }
  return true;
}

