function areSimilar(mat, k) {
  const grid = mat.map(r => r.slice());
  for (let step = 0; step < k; step++) {
    grid.forEach((r, i) => {
      if (i % 2 === 0) r.push(r.shift());
      else r.unshift(r.pop());
    });
  }
  return grid.every((r, i) => r.every((v, j) => v === mat[i][j]));
}

