function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const m = size === 'large' ? pick(20, 25) : pick(1, 4);
  const n = size === 'large' ? pick(20, 25) : pick(1, 6);
  const k = pick(1, 50);
  const top = size === 'large' ? 25 : pick(1, 3);
  // A row survives exactly when it repeats with period gcd(k, n); build such rows half the time.
  const period = gcd(k % n, n) || n;
  const periodic = rand() < 0.5;
  const mat = [];
  for (let i = 0; i < m; i++) {
    const pattern = Array.from({ length: periodic ? period : n }, () => pick(1, top));
    mat.push(Array.from({ length: n }, (_, j) => pattern[j % pattern.length]));
  }
  // Sometimes break one cell of a periodic grid so the answer usually turns false.
  if (periodic && rand() < 0.4) {
    const i = pick(0, m - 1), j = pick(0, n - 1);
    mat[i][j] = pick(1, 25);
  }
  return [mat, k];
}
